SERVICES = {'P23': 'guided-model-call', 'P01': 'guided-h01-gateway', 'P02': 'guided-h02-document-app', 'P03': 'guided-h03-sync-app', 'P04': 'guided-h04-guardrail-app', 'P05': 'guided-h05-nemo-dialog', 'P06': 'guided-h06-nemo-action', 'P07': 'guided-h07-content-safety', 'P08': 'guided-h08-self-check-input', 'P09': 'guided-h09-presidio-redaction', 'P10': 'guided-h10-self-check-output', 'P11': 'guided-h11-rag-provenance', 'P12': 'guided-h12-application-pipeline', 'P13': 'guided-h13-promptfoo', 'P14': 'guided-h14-garak', 'P15': 'guided-h15-pyrit', 'P16': 'guided-h16-policy-promotion', 'P18': 'guided-h18-queries', 'P22': 'guided-h22-host', 'P21': 'guided-h21-host', 'P19': 'guided-h19-investigation', 'P17': 'guided-h17-telemetry', 'P20': 'guided-h20-alerts'}

def diagnosis(problem, status, observed=None):
    if problem not in FILES:
        return None
    result = {"file": FILES[problem], "next_action": CHECKS[problem],
              "cause": "서비스가 요청을 완료하지 못했습니다. 구체적인 실행 원인은 아래 기록에서 확인하세요.",
              "model_calls": "기록 없음", "evidence": "확인 안내"}
    if problem in SERVICES and status >= 500:
        result["log_command"] = "cd ~/owasp-llm-lab-setup-guide/llm-security-control-plane\ndocker compose --env-file .state/guided-course.env -f ../examples/security-monitoring/compose.guided.yaml logs --tail 80 " + SERVICES[problem]
    if status in (401, 403):
        result.update(cause="인증 또는 접근 권한 검사에서 요청이 거부됐습니다.",
                      next_action="화면의 세션을 갱신하고 해당 미션의 AWS 상태·호출 권한을 확인하세요.")
    elif status == 409:
        result.update(cause="작업이 진행 중이거나 필요한 준비 상태가 충족되지 않았습니다.",
                      next_action="진행 중인 작업이 끝났는지 확인하고 AWS 상태 확인 결과를 확인하세요.")
    elif status == 422:
        result.update(cause="요청 형식 또는 입력값 검사에서 멈췄습니다.")
    if isinstance(observed, dict):
        # Only structured, server-generated fields cross the UI boundary.
        for key in ("cause", "field", "next_action", "stopped_stage", "model_calls", "evidence"):
            value = observed.get(key)
            if isinstance(value, str) and len(value) <= 600:
                result[key] = value
    return result
